def correct_bracketing(brackets: str):
    # Check if the input string contains only '<' and '>' characters
    if set(brackets) != {'<', '>'}:
        return False

    # Check if the number of opening brackets is equal to the number of closing brackets
    if brackets.count('<') != brackets.count('>'):
        return False

    # Check if the opening brackets are correctly matched with closing brackets
    stack = []
    for bracket in brackets:
        if bracket == '<':
            stack.append(bracket)
        elif bracket == '>':
            if not stack:
                return False
            stack.pop()

    return len(stack) == 0
