def right_angle_triangle(a, b, c):
    # Check if the given sides can form a triangle
    if a + b <= c or a + c <= b or b + c <= a:
        return False

    # Find the longest side of the triangle
    hypotenuse = max(a, b, c)

    # Find the other two sides
    if hypotenuse == a:
        side1 = b
        side2 = c
    elif hypotenuse == b:
        side1 = a
        side2 = c
    else:
        side1 = a
        side2 = b

    # Check if the Pythagorean theorem holds true
    if side1**2 + side2**2 == hypotenuse**2:
        return True
