    if not numbers:
        return []

    rolling_max_list = []
    max_val = numbers[0]
    rolling_max_list.append(max_val)

    for i in range(1, len(numbers)):
        max_val = max(numbers[i], max_val)
        rolling_max_list.append(max_val)

    return rolling_max_list

